------------------------------------------------------------
----- ROOT ID FUNCTION FOR: [Category].[parentCategoryID]
------------------------------------------------------------
IF OBJECT_ID('[higherlogic_vanilla].[fnCategoryparentCategoryID_GetRootID]', 'IF') IS NOT NULL
    DROP FUNCTION [higherlogic_vanilla].[fnCategoryparentCategoryID_GetRootID];
GO

CREATE FUNCTION [higherlogic_vanilla].[fnCategoryparentCategoryID_GetRootID]
(
    @RecordID int,
    @ParentID int
)
RETURNS TABLE
AS
RETURN
(
    WITH CTE_RootParent AS (
        SELECT
            [categoryID],
            [parentCategoryID],
            [categoryID] AS [RootParentID],
            0 AS [Depth]
        FROM
            [higherlogic_vanilla].[Category]
        WHERE
            [categoryID] = COALESCE(@ParentID, @RecordID)

        UNION ALL

        SELECT
            c.[categoryID],
            c.[parentCategoryID],
            c.[categoryID] AS [RootParentID],
            p.[Depth] + 1 AS [Depth]
        FROM
            [higherlogic_vanilla].[Category] c
        INNER JOIN
            CTE_RootParent p ON c.[categoryID] = p.[parentCategoryID]
        WHERE
            p.[Depth] < 100
    )
    SELECT TOP 1
        [RootParentID] AS RootID
    FROM
        CTE_RootParent
    WHERE
        [parentCategoryID] IS NULL
    ORDER BY
        [RootParentID]
);
GO

