CREATE FUNCTION [higherlogic_vanilla].[fnUserinviteUserID_GetRootID]
(
    @RecordID int,
    @ParentID int
)
RETURNS TABLE
AS
RETURN
(
    WITH CTE_RootParent AS (
        SELECT
            [userID],
            [inviteUserID],
            [userID] AS [RootParentID],
            0 AS [Depth]
        FROM
            [higherlogic_vanilla].[User]
        WHERE
            [userID] = COALESCE(@ParentID, @RecordID)

        UNION ALL

        SELECT
            c.[userID],
            c.[inviteUserID],
            c.[userID] AS [RootParentID],
            p.[Depth] + 1 AS [Depth]
        FROM
            [higherlogic_vanilla].[User] c
        INNER JOIN
            CTE_RootParent p ON c.[userID] = p.[inviteUserID]
        WHERE
            p.[Depth] < 100
    )
    SELECT TOP 1
        [RootParentID] AS RootID
    FROM
        CTE_RootParent
    WHERE
        [inviteUserID] IS NULL
    ORDER BY
        [RootParentID]
);
GO

